\label{lemma:fmv}
    For the boundary data $f\in \mathcal{C}_D,$ we have
    \begin{align}
        w=\Delta^{-1}P^1_N f \text{ iff } w(x):= w(r\eta)=\frac{1}{4\pi}\int_{|\xi|=1}K_N(r\eta, \xi) f(\xi)\; d\xi, \text{ for all  } x \in B_1
    \end{align}
    with the truncated kernel $K_N(r\eta, \xi)=\sum_{n=0}^{N}r^n (2n+1)L_n(\eta\cdot\xi).$

Let $x=r\eta\in B_1$, where $0\leq r <1$ and $\eta\in \partial B_1$. Now the series $\sum_{n=0}^{\infty} (2n+1)r^nL_n(\eta\cdot\xi)$ converges uniformly to $\frac{1-r^2}{(1-2r(\eta.\xi)+r^2)^{\frac{3}{2}}}$ for $r<1$ as $|\eta\cdot\xi|=1.$ Therefore the $L^2$-orthogonal projection of the kernel on the finite dimensional space $\mathcal{S}_N^1$ (cf. \eqref{eqn:bsp}) is represented by $K_N(r\eta, \xi):=P_N^1K(r\eta, \xi)=\sum_{n=0}^{N} (2n+1)r^nL_n(\eta\cdot\xi).$ Consequently, we get
    \begin{align*}
       w(x)&=\frac{1}{4\pi}\int_{|\xi|=1}K(r\eta, \xi) P_N^1 f(\xi)\; d\xi=\frac{1}{4\pi}\int_{|\xi|=1}P_N^1 K(r\eta, \xi) f(\xi)\; d\xi\\
       &=\frac{1}{4\pi}\int_{|\xi|=1}K_N(r\eta, \xi)f(\xi)\; d\xi. 
    \end{align*}

\label{thm:main}
The projected Poisson kernel satisfies: for all $N\geq 4$ odd, 
\begin{align}\label{eqn:mrs}
\begin{split}
     \tilde{K}_N(r, \psi)&=\sum_{n=0}^{N}r^n(2n+1)L_n(\cos{\psi}) \geq 0 \text{ for all } \psi\in [0,\pi] \text{ with }r\leq r_N,\\
    \text{ with } r_N&=\left(1-\frac{2\ln{(2(N+1))}}{N+1}\right).
\end{split}
\end{align}

We have to find $r_N=\arg \max\{ r \,|\, \Tilde{K}_N(r, \psi)\geq 0, \forall \psi\in [0, \pi] \}$. From numerical experiments, we have observed that $r_N$ coincides with
\begin{align}
    r_N^*=\arg\max\{r \; | \; S_N(r,\psi)=\sum_{n=0}^{N}(-1)^n r^n(2n+1)\sin^{2n}{\left(\frac{\psi}{2}\right)}\geq 0, \forall \; \psi\in [0,\pi]\},
\end{align}
 for $N$ odd.





Let $x=r\sin^{2}{\frac{\psi}{2}}\in [0, 1)$. We compute the finite sum for odd $N$ and obtain
\begin{align*}
    S_N(x)&=\sum_{n=0}^{N}(-1)^n(2n+1)x^n\\
    &=\frac{1-x-(2N+3)x^{N+1}-(2N+1)x^{N+2}}{(1+x)^2}.
\end{align*}
We insert the value of $x$ and obtain
\begin{align*}
    S_N(r,\psi)=\frac{1-r\sin^2{\left(\frac{\psi}{2}\right)}-(2N+3)r^{N+1}\sin^{2N+2}{\left(\frac{\psi}{2}\right)}-(2N+1)r^{N+2}\sin^{2N+4}{\left(\frac{\psi}{2}\right)}}{\left(1+r\sin^2{\left(\frac{\psi}{2}\right)}\right)^2}.
\end{align*}
We differentiate $S_N(r,\psi)$ partially with respect to $\psi$ and arrive at
\begin{align*}
    \frac{\partial S_N}{\partial \psi}&=\frac{\cos{\left(\frac{\psi}{2}\right)}}{\left(1+r\sin^2{\left(\frac{\psi}{2}\right)}\right)^3}\left[-3r\sin{\left(\frac{\psi}{2}\right)}+r^2\sin^3{\left(\frac{\psi}{2}\right)}-(2N^2+3N+1)r^{N+1}\sin^{2N+1}{\left(\frac{\psi}{2}\right)}\right.\\
    &\left.-(4N^2+4N-3)r^{N+2}\sin^{2N+3}{\left(\frac{\psi}{2}\right)}-(2N^2+N)r^{N+3}\sin^{2N+5}{\left(\frac{\psi}{2}\right)}\right]\\
    &\leq 0.
\end{align*}
Therefore, the function $S_N(r, \psi)$ is decreasing with respect to $\psi.$ Hence, the global minimum value of $S_N$ with respect to $\psi$ will be attained at the endpoint. So, we can write
\begin{align*}
    \min_{\psi\in [0, \pi]} S_N(r,\psi)=S_N(r,\pi)=\sum_{n=0}^{N}(-1)^n(2n+1)r^n.
\end{align*}
Next, we would like to find the global minimum value of $\tilde{K}_N(r,\psi)$ with respect to $\psi$ for $\psi\in [0,\pi]$. We calculate
\begin{align*}
   \frac{\partial \tilde{K}_N}{\partial \psi}&=-\sum_{n=0}^{N}r^n(2n+1)(\sin{\psi})L'_n(\cos{\psi}),\\
   \frac{\partial^2 \tilde{K}_N}{\partial \psi^2}&=-\sum_{n=0}^{N}r^n(2n+1)[\cos{\psi}L'_n(\cos{\psi})-\sin^2{\psi}L''_n(\cos{\psi})].
\end{align*}





Now, $\partial_\psi \tilde{K}_N(r,\psi)=0$ gives $\psi=0, \pi $ or $L'_n(\cos{\psi})=0.$ 
Computing the second derivatives at the point $\psi=0$ gives ${                                            
  \left.\kern-\nulldelimiterspace                                           
  \frac{\partial^2 \tilde{K}_N}{\partial \psi^2}               
  \mathchoice{\vphantom{\big|}}{}{}{}                                              
  \right|_{\psi=0}                        
  }=-\sum_{n=0}^{N}r^n(2n+1)L'_n(1)=-\sum_{n=0}^{N}r^n(2n+1)\frac{n(n+1)}{2}\leq 0$. Therefore, $\tilde{K}_N(r,\psi)$ attains its maximum value with respect to $\psi$ at $\psi=0.$ Next, we compute the value at $\psi=\pi$, and we get
\begin{align*}
    {                                            
  \left.\kern-\nulldelimiterspace                                           
  \frac{\partial^2 \tilde{K}_N}{\partial \psi^2}               
  \mathchoice{\vphantom{\big|}}{}{}{}                                              
  \right|_{\psi=\pi}                        
  }&=\sum_{n=0}^{N}r^n(2n+1)L'_n(-1)=\frac{1}{2}\sum_{n=1}^{N}(-1)^{n+1}n(n+1)(2n+1)r^n.
\end{align*}
We need to mention the fact that $N$ is odd now plays an important role in determining the sign of the second derivative. We chose $a_n=n(n+1)(2n+1)r^n,$ $n\in \mathbb{N}$ and write the expression as
\begin{align*}
    {                                            
  \left.\kern-\nulldelimiterspace                                           
  \frac{\partial^2 \tilde{K}_N}{\partial \psi^2}               
  \mathchoice{\vphantom{\big|}}{}{}{}                                              
  \right|_{\psi=\pi}                        
  }=\frac{1}{2}\left[(a_1-a_2)+(a_3-a_4)+. . .+(a_{N-2}-a_{N-1})+a_{N}\right].
\end{align*}
Therefore, ${                                            
  \left.\kern-\nulldelimiterspace                                           
  \frac{\partial^2 \tilde{K}_N}{\partial \psi^2}               
  \mathchoice{\vphantom{\big|}}{}{}{}                                              
  \right|_{\psi=\pi}                        
  }\geq 0$ if and only of $\frac{a_{n+1}}{a_n}\leq 1,$ for all $1\leq n \leq N.$ Then we compute
\begin{align*}
    \frac{a_{n+1}}{a_{n}}=\frac{(2n+3)(n+2)}{n(2n+1)}r\leq 1
\end{align*}
iff $r \leq \frac{n(2n+1)}{(2n+3)(n+2)}$. Therefore, we prove that $\tilde{K}_N(r,\psi)$ attains global minimum value with respect to $\psi$ at $\psi=\pi$ for $r\leq \frac{n(2n+1)}{(2n+3)(n+2)}=r(N).$ Consequently, we deduce that
\begin{align}
    \min_{\psi\in [0,\pi]}\tilde{K}_N(r,\psi)=\tilde{K}_N(r,\pi)=S_N(r,\pi)=\min_{\psi\in[0,\pi]}S_N(r,\psi) \text{ for all } 0\leq r <r(N).
\end{align}
We now have to check the positivity of $K_N(r,\pi)$. The expression of $K_N(r,\pi)$ is given by  
\begin{align*}
    \tilde{K}_N(r,\pi)&=\sum_{n=0}^{N}(-1)^n(2n+1)r^n\\
    &=\frac{1-r-(2N+3)r^{N+1}-(2N+1)r^{N+2}}{(1+r)^2}.
\end{align*}
The denominator is strictly positive for $0\leq r <1.$ We have to analyze the sign of the numerator. We start with
\begin{align*}
    1-r-(2N+3)r^{N+1}-(2N+1)r^{N+2}&\geq 1-r-4(N+1)r^{N+1}=y-4x(1-y)^x
\end{align*}
with $y=1-r$ and $x=N+1.$ We have to find appropriate $y=y(x)$ such that
\begin{align}
    y-4x(1-y)^x\geq 0
\end{align}
holds. We use the Lambert function to achieve our goal. The Lambert function $W(x)$ is a unique solution of the equation $W(x)e^{W(x)}=x$ for $x\geq 0.$ We take $\tilde{y}:=\frac{W(4x^2)}{x}$. Therefore, we get $W(4x^2)=x\tilde{y}$. We know $W(4x^2)$ satisfies the relation $W(4x^2) e^{W(4x^2)}=4x^2$. Therefore, we obtain $\tilde{y} e^{x\tilde{y}}=4x.$ We can express $\tilde{y}$ as 
\begin{align*}
    \tilde{y}=4xe^{-x\tilde{y}}.
\end{align*}
We know from \cite{hassani2012approximation} that $W(x)<\ln{x}$ for $x>e.$ Therefore, we have $\tilde{y}=\frac{W(4x^2)}{x}\leq \frac{2\ln{(2x)}}{x}$. For all $N\geq 4,$ we get $0<\tilde{y}<1.$ Then, we use the inequality $\ln{(1-\tilde{y})}\leq -\tilde{y}$ to derive
\begin{align*}
    4x(1-\tilde{y})^x \leq 4xe^{-x\tilde{y}}=\tilde{y}.
\end{align*}
Therefore, $\tilde{y}-4x(1-\tilde{y})^x\geq 0$ holds for $\tilde{y}=\frac{W(4x^2)}{x}.$ The function $t\mapsto t-4x(1-t)^x$ is monotonically increasing on $[0,1).$ Consequently, we have there exists $y_0$ with $\tilde{y}\leq y_0<1$ such that
\begin{align}\label{eqn:ey}
     y-4x(1-y)^x\geq 0 \text{ for all } y\in [y_0,1).
\end{align}
We have for all $N\geq 4$, $\tilde{y}=\frac{W(4x^2)}{x}\leq \frac{2\ln{(2x)}}{x}:=y_0.$ We now insert $y=(1-r)$ and $x=N+1$ in \eqref{eqn:ey} to deduce that
\begin{align*}
    1-r-4(N+1)r^{N+1}\geq 0 \text{ if }r\leq 1-\frac{2\ln{(2(N+1))}}{N+1}.
\end{align*}
This completes the proof of the theorem.

\label{thm:nmp}
    For every odd $N\geq 4$, the following properties holds 
    \begin{align}
       K_N(r\eta, \xi)&\geq 0 \text{ for all } r\eta \in B_1^{+}(N), \xi\in \partial B_1, \label{eqn:ptk}\\
      \frac{1}{4\pi}\int_{|\xi|=1}K_N(r\eta, \xi)\; d\xi &=1 \text{ for all }  0\leq r<1, \label{eqn:atk}\\
       \min_{\xi\in \partial B_1} f(\xi) \leq (\Delta^{-1}_1P_N^1f)(r\eta, \xi)&\leq \max_{\xi\in \partial B_1} f(\xi), \text{ for all }f\in \mathcal{C}_D \text{ and }r\eta\in B_1^{+}(N), \label{eqn:ulbtk}
       \end{align}
       where $K_N(r\eta, \xi)$ is explicitly given in the Lemma \ref{lemma:fmv}.

We have from \eqref{eqn:eqtk} that $K_N(r\eta, \xi)=\tilde{K}_N(r,\psi),$ for all $(r,\psi)\in [0,1)\times [0,\pi].$ Accordingly, the result \eqref{eqn:ptk} follows from Theorem \ref{thm:main}. We know that $K_N=P_N^1K$ and therefore
    \begin{align*}
        \frac{1}{4\pi}\int_{|\xi|=1}K_N(r\eta, \xi)\; d\xi=\frac{1}{4\pi}\int_{|\xi|=1}K(r\eta, \xi)P_N^1(1)\; d\xi=\frac{1}{4\pi}\int_{|\xi|=1}K(r\eta, \xi)\; d\xi=1
    \end{align*}
   by \eqref{eqn:ave}. This proves \eqref{eqn:atk}. From Lemma \ref{lemma:fmv}, we obtain
   \begin{align*}
       \Delta^{-1}P_N^1f(x):=\Delta^{-1}P_N^1f(r\eta)=\frac{1}{4\pi}\int_{|\xi|=1}K_N(r\eta, \xi)f(\xi)\; d\xi, \text{ for all }x\in B_1.
   \end{align*}
   Therefore, for all $r\eta, r\xi\in B_1^{+}(N),$ we have $K_N(r\eta, \xi)\geq0.$ Together with \eqref{eqn:atk} this implies \eqref{eqn:ulbtk}.
